components.content:
/* Carte principale - Sticky */
.sfc-card {
  position: sticky;
  top: 20px;
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  padding: 24px;
  font-family: 'Segoe UI', Roboto, sans-serif;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
}
.sfc-card h3 {
  font-size: 18px;
  font-weight: 700;
  color: #111827;
  margin: 0 0 4px;
}
.sfc-card .sfc-subtitle {
  font-size: 13.5px;
  color: #4b5563;
  margin: 0 0 18px;
  line-height: 1.5;
}
.sfc-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 12px;
  font-size: 13.5px;
  color: #374151;
  line-height: 1.5;
}
.sfc-row .sfc-ico {
  flex-shrink: 0;
  width: 20px;
  text-align: center;
  font-size: 15px;
  margin-top: 1px;
  color: #4b5563;
}
.sfc-row a {
  color: #3b82f6;
  text-decoration: none;
}
.sfc-row a:hover {
  text-decoration: underline;
}
.sfc-row strong {
  color: #111827;
  font-weight: 600;
}
.sfc-stitle {
  font-size: 16px;
  font-weight: 700;
  color: #111827;
  margin: 20px 0 12px;
  padding-top: 16px;
  border-top: 1px solid #e5e7eb;
}
.sfc-boxes {
  display: flex;
  gap: 10px;
  margin-bottom: 14px;
  width: 100%;
}
.sfc-box {
  flex: 1;
  background: #f9fafb;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  padding: 12px;
}
.sfc-box .sfc-lbl {
  font-size: 11.5px;
  color: #6b7280;
  font-weight: 500;
  margin: 0 0 6px;
  line-height: 1.3;
}
.sfc-box .sfc-val {
  font-size: 14px;
  font-weight: 700;
  color: #111827;
  margin: 0;
}
.sfc-box .sfc-sub {
  font-size: 11px;
  color: #9ca3af;
  font-weight: 400;
}
.sfc-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #16a34a;
  font-size: 13px;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  margin-top: 5px;
}
.sfc-link:hover {
  text-decoration: underline;
}
.sfc-link-ico {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  background: #16a34a;
  color: #fff;
  border-radius: 50%;
  font-size: 11px;
  font-weight: 700;
}

actions.customAction:
const recapDiv = document.getElementById("recapDisplay");
if (!recapDiv) return;

const lang = (instance && instance.options && instance.options.language) || form.language || "fr";
const dictionary = (form && form.i18n && form.i18n[lang]) || {};
const tr = (text) => dictionary[text] || text;
const excludeTypes = ["button", "file", "container", "panel", "columns", "htmlelement"];
const excludeKeys = new Set([
  "luEtApprouve",
  "checkboxExactitudePieces",
  "checkboxEngagementAudit",
  "checkboxConnaissanceInfraction",
  "startButton",
  "stylesCssSidebar",
  "stickyInjector",
  "htmlNotificationCorrection",
  "htmlRappelFrais",
  "precedent4",
  "next4"
]);

function isPlainObject(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isEmptyValue(value) {
  if (value === null || value === undefined || value === "") return true;
  if (Array.isArray(value)) return value.length === 0;
  if (isPlainObject(value)) return Object.keys(value).length === 0;
  return false;
}

function formatDate(value) {
  if (typeof value !== "string") return value;
  if (/^\d{4}-\d{2}-\d{2}(T.*)?$/.test(value)) {
    const date = new Date(value);
    if (!Number.isNaN(date.getTime())) {
      return date.toLocaleDateString(lang === "en" ? "en-GB" : "fr-FR");
    }
  }
  return value;
}

function getDisplayValue(value) {
  if (value === null || value === undefined) return "";
  if (Array.isArray(value)) {
    return value
      .map((item) => getDisplayValue(item))
      .filter((item) => item !== "")
      .join(", ");
  }
  if (isPlainObject(value)) {
    const preferredKeys = ["label", "libelle", "nom", "nomCentre", "Prefecture", "Commune", "name"];
    for (const key of preferredKeys) {
      if (value[key] !== undefined && value[key] !== null && value[key] !== "") {
        return String(value[key]);
      }
    }
    return Object.values(value)
      .map((item) => getDisplayValue(item))
      .filter((item) => item !== "")
      .join(", ");
  }
  return String(formatDate(value));
}

function resolveSelectLabel(component, rawValue) {
  const comp = instance.root.getComponent(component.key);
  if (!comp || !Array.isArray(comp.selectOptions) || comp.selectOptions.length === 0) {
    return getDisplayValue(rawValue);
  }

  if (Array.isArray(rawValue)) {
    return rawValue
      .map((entry) => resolveSelectLabel(component, entry))
      .filter(Boolean)
      .join(", ");
  }

  const serialized = JSON.stringify(rawValue);
  const match = comp.selectOptions.find((option) => {
    return JSON.stringify(option.value) === serialized || String(option.value) === String(rawValue);
  });
  return match ? match.label : getDisplayValue(rawValue);
}

function resolveRadioLabel(component, rawValue) {
  if (!Array.isArray(component.values)) return getDisplayValue(rawValue);
  const match = component.values.find((option) => String(option.value) === String(rawValue));
  return match ? match.label : getDisplayValue(rawValue);
}

const collectedRows = [];

utils.eachComponent(form.components, (component) => {
  if (!component || excludeTypes.includes(component.type) || excludeKeys.has(component.key) || component.hidden) {
    return;
  }

  const rawValue = data[component.key];
  if (isEmptyValue(rawValue)) {
    return;
  }

  let displayValue = "";
  if (component.type === "select") {
    displayValue = resolveSelectLabel(component, rawValue);
  } else if (component.type === "radio") {
    displayValue = resolveRadioLabel(component, rawValue);
  } else {
    displayValue = getDisplayValue(rawValue);
  }

  if (!displayValue) {
    return;
  }

  collectedRows.push({
    label: component.label || component.key,
    value: displayValue
  });
}, false);

const wrapper = document.createElement("div");
wrapper.className = "recap-container";

const style = document.createElement("style");
style.textContent = `
  .recap-container { width: 100%; margin: 0 auto 20px; }
  .recap-table { width: 100%; border-collapse: collapse; }
  .recap-table thead th {
    background-color: #EEEEEE;
    color: #000;
    font-weight: 700;
    padding: 10px;
    border: 3px solid #ccc;
    text-align: center;
    font-family: Poppins, Arial, sans-serif;
    font-size: 16px;
  }
  .recap-table td {
    border: 3px solid #ccc;
    padding: 8px;
    text-align: left;
    font-size: 14px;
    font-family: Poppins, Arial, sans-serif;
    word-break: break-word;
    vertical-align: top;
  }
  .recap-empty {
    padding: 14px;
    border: 1px solid #E5E7EB;
    border-radius: 8px;
    background: #F9FAFB;
    color: #4B5563;
  }
`;
wrapper.appendChild(style);

if (collectedRows.length === 0) {
  const emptyTitle = document.createElement("p");
  emptyTitle.className = "recap-empty";
  emptyTitle.textContent = tr("Aucune donnée exploitable n'est disponible pour le récapitulatif.");
  wrapper.appendChild(emptyTitle);
  recapDiv.replaceChildren(wrapper);
  return;
}

const table = document.createElement("table");
table.className = "recap-table";

const thead = document.createElement("thead");
const headerRow = document.createElement("tr");
["#", tr("Champs du formulaire"), tr("Données saisies")].forEach((text) => {
  const th = document.createElement("th");
  th.textContent = text;
  headerRow.appendChild(th);
});
thead.appendChild(headerRow);
table.appendChild(thead);

const tbody = document.createElement("tbody");
collectedRows.forEach((row, index) => {
  const trRow = document.createElement("tr");

  const indexCell = document.createElement("td");
  indexCell.style.width = "5%";
  indexCell.style.textAlign = "center";
  indexCell.textContent = String(index + 1);
  trRow.appendChild(indexCell);

  const labelCell = document.createElement("td");
  labelCell.style.width = "45%";
  labelCell.textContent = row.label || tr("Non renseigné");
  trRow.appendChild(labelCell);

  const valueCell = document.createElement("td");
  valueCell.style.width = "50%";
  valueCell.textContent = row.value || tr("Non renseigné");
  trRow.appendChild(valueCell);

  tbody.appendChild(trRow);
});
table.appendChild(tbody);
wrapper.appendChild(table);
recapDiv.replaceChildren(wrapper);
